export function getHinoTrucks(): HinoTruckProduct[] {
  return HINO_TRUCKS;
}

export function getHinoTruckBySlug(slug: string): HinoTruckProduct | undefined {
  return HINO_TRUCKS.find((truck) => truck.slug === slug);
}

export function getRelatedHinoTrucks(currentSlug: string, limit = 3): HinoTruckProduct[] {
  const current = getHinoTruckBySlug(currentSlug);
  if (!current) return HINO_TRUCKS.slice(0, limit);
  return HINO_TRUCKS
    .filter((t) => t.slug !== currentSlug && (t.categorySlug === current.categorySlug || t.series === current.series))
    .slice(0, limit);
}
